// Benchmark run order
// - Classic: runs each bench once in the order above, and repeats n times.
// - Isolated: runs each bench n times in isolation
enum class BenchOrder : int {Classic, Isolated};
BenchOrder order = BenchOrder::Classic;

template <typename T>
