FutharkStream<double>::~FutharkStream()
{
  if (this->a) {
    futhark_free_f64_1d(this->ctx, (futhark_f64_1d*)this->a);
  }
  if (this->b) {
    futhark_free_f64_1d(this->ctx, (futhark_f64_1d*)this->b);
